-- =====================================================================
-- WEB-GIS COFFEE SHOP MARKET GAP ANALYSIS (KOTA BOGOR)
-- COMPLETE SETUP: EXTENSIONS, TABLES, RLS, & COMPLETE SEED DATA
-- =====================================================================

-- 1. EXTENSIONS
CREATE EXTENSION IF NOT EXISTS postgis;
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- 2. DROP TABLES
DROP TABLE IF EXISTS grid_points CASCADE;
DROP TABLE IF EXISTS crowd_centers CASCADE;
DROP TABLE IF EXISTS road_networks CASCADE;
DROP TABLE IF EXISTS competitors CASCADE;
DROP TABLE IF EXISTS population_data CASCADE;
DROP TABLE IF EXISTS districts CASCADE;

-- 3. CREATE TABLES
CREATE TABLE districts (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    district_name VARCHAR(100) NOT NULL UNIQUE,
    population INT NOT NULL,
    area_km2 NUMERIC(8, 2) NOT NULL,
    density_per_km2 INT NOT NULL,
    color VARCHAR(20) DEFAULT '#3B82F6',
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

CREATE TABLE population_data (
    id SERIAL PRIMARY KEY,
    bps_district_name VARCHAR(100) NOT NULL UNIQUE,
    population_count INT NOT NULL,
    density_per_km2 INT NOT NULL,
    growth_rate NUMERIC(4, 2) DEFAULT 1.2,
    updated_year INT DEFAULT 2024
);

CREATE TABLE competitors (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    name VARCHAR(255) NOT NULL,
    category VARCHAR(100) DEFAULT 'Coffee Shop',
    district_name VARCHAR(100),
    address TEXT,
    latitude FLOAT8 NOT NULL,
    longitude FLOAT8 NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

CREATE TABLE road_networks (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    name VARCHAR(255) NOT NULL,
    road_type VARCHAR(50) NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

CREATE TABLE crowd_centers (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    name VARCHAR(255) NOT NULL,
    category VARCHAR(50) NOT NULL,
    district_name VARCHAR(100),
    description TEXT,
    latitude FLOAT8 NOT NULL,
    longitude FLOAT8 NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

CREATE TABLE grid_points (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    latitude FLOAT8 NOT NULL,
    longitude FLOAT8 NOT NULL,
    district_name VARCHAR(100) NOT NULL,
    c1_dist_competitor FLOAT8 NOT NULL,
    c2_population FLOAT8 NOT NULL,
    c3_dist_road FLOAT8 NOT NULL,
    c4_dist_crowd FLOAT8 NOT NULL,
    nearest_competitor VARCHAR(255),
    nearest_road VARCHAR(255),
    nearest_crowd VARCHAR(255),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 4. ROW LEVEL SECURITY (RLS) POLICIES
-- Enable public read access for all tables

ALTER TABLE districts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Allow public select on districts" ON districts FOR SELECT TO public USING (true);
CREATE POLICY "Allow anon all on districts" ON districts FOR ALL TO anon USING (true) WITH CHECK (true);

ALTER TABLE population_data ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Allow public select on population_data" ON population_data FOR SELECT TO public USING (true);
CREATE POLICY "Allow anon all on population_data" ON population_data FOR ALL TO anon USING (true) WITH CHECK (true);

ALTER TABLE competitors ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Allow public select on competitors" ON competitors FOR SELECT TO public USING (true);
CREATE POLICY "Allow anon all on competitors" ON competitors FOR ALL TO anon USING (true) WITH CHECK (true);

ALTER TABLE road_networks ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Allow public select on road_networks" ON road_networks FOR SELECT TO public USING (true);
CREATE POLICY "Allow anon all on road_networks" ON road_networks FOR ALL TO anon USING (true) WITH CHECK (true);

ALTER TABLE crowd_centers ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Allow public select on crowd_centers" ON crowd_centers FOR SELECT TO public USING (true);
CREATE POLICY "Allow anon all on crowd_centers" ON crowd_centers FOR ALL TO anon USING (true) WITH CHECK (true);

ALTER TABLE grid_points ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Allow public select on grid_points" ON grid_points FOR SELECT TO public USING (true);
CREATE POLICY "Allow anon all on grid_points" ON grid_points FOR ALL TO anon USING (true) WITH CHECK (true);

